mapper.sql:
from cm_collection c join cm_collection_current cur on cur.collection_id=c.id
join cm_collection_revision r on r.id=cur.collection_revision_id
join cm_exam_certification cert on cert.id=c.certification_id and cert.status='0'
where c.id=#{collectionId} and c.status='0' and c.collection_type=#{collectionType}
  and r.status='published' and r.collection_type=#{collectionType}

mapper.select:
select  from cm_session_question sq join cm_learning_session s on s.id=sq.session_id
join cm_question_attempt a on a.session_question_id=sq.id and a.attempt_no=1 join cm_attempt_answer aa on aa.attempt_id=a.id
where sq.session_id=#{sessionId} and s.user_id=#{userId} and sq.question_order=#{questionOrder}
